import React from 'react';
import { motion } from 'framer-motion';

/**
 * ExplanationPanel — Renders the multi-section XAI explanation
 * with structured formatting instead of dumping raw text.
 */
const ExplanationPanel = ({ explanation }) => {
  if (!explanation) return null;

  // Parse sections from the explanation text
  const sections = parseSections(explanation);

  return (
    <motion.div
      className="explanation-panel"
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.45, delay: 0.35 }}
    >
      <div className="card-title expl">
        <div className="card-ico ico-c" style={{ marginLeft: 0 }}>📝</div>
        <span className="card-title-text">Model Analysis</span>
        <span style={{
          marginLeft:'auto', fontFamily:'JetBrains Mono,monospace',
          fontSize:9, color:'var(--muted)', letterSpacing:'.1em'
        }}>
          SHAP + ATTENTION + REGIME
        </span>
      </div>

      <div className="explanation-sections">
        {sections.map((section, i) => (
          <div key={i} className={`expl-section ${section.type}`}>
            {section.title && (
              <div className="expl-section-title">
                <span className="expl-icon">{section.icon}</span>
                {section.title}
              </div>
            )}
            <div className="expl-section-body">
              {section.lines.map((line, j) => (
                <div key={j} className="expl-line">{line}</div>
              ))}
            </div>
          </div>
        ))}
      </div>
    </motion.div>
  );
};

/**
 * Parse the explanation text into structured sections.
 * Looks for emoji-prefixed headers like "📈  PRICE FORECAST"
 */
function parseSections(text) {
  const lines = text.split('\n');
  const sections = [];
  let current = null;

  // Section header icons and their CSS classes
  const sectionMap = {
    '📈': { type: 'forecast', icon: '📈' },
    '📉': { type: 'forecast', icon: '📉' },
    '🎯': { type: 'confidence', icon: '🎯' },
    '📊': { type: 'regime', icon: '📊' },
    '😌': { type: 'regime', icon: '😌' },
    '⚡': { type: 'ensemble', icon: '⚡' },
    '🔑': { type: 'shap', icon: '🔑' },
    '🧠': { type: 'xai', icon: '🧠' },
    '📋': { type: 'disclaimer', icon: '📋' },
  };

  for (const line of lines) {
    const trimmed = line.trim();

    // Skip separator lines
    if (/^[─━─]{4,}$/.test(trimmed)) continue;

    // Check if this is a section header (starts with emoji)
    const firstChar = [...trimmed][0];
    if (sectionMap[firstChar]) {
      // Save previous section
      if (current) sections.push(current);
      const { type, icon } = sectionMap[firstChar];
      // Extract title (remove leading emoji + spaces)
      const title = trimmed.replace(/^.{1,2}\s*/, '');
      current = { type, icon, title, lines: [] };
    } else if (trimmed.startsWith('ATHENA XAI')) {
      // Report header
      if (current) sections.push(current);
      current = { type: 'header', icon: '📄', title: trimmed, lines: [] };
    } else if (current) {
      // Content under current section — trim leading spaces for readability
      const cleaned = line.replace(/^\s{3}/, '');
      if (cleaned.trim()) {
        current.lines.push(cleaned);
      }
    }
  }
  if (current) sections.push(current);
  return sections;
}

export default ExplanationPanel;
